"""Probe the order service: walk pages until the first non-200 and dump it in full."""
import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


def call(method, path, token=None):
    req = urllib.request.Request(BASE + path, method=method, data=b"" if method == "POST" else None)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode()


def main():
    status, headers, body = call("POST", "/token")
    token = json.loads(body)["token"]
    print("token:", token)
    for page in range(1, 31):
        status, headers, body = call("GET", f"/orders?page={page}", token)
        print(f"page {page}: status={status} bytes={len(body)}")
        if status != 200:
            print("HEADERS:", json.dumps(headers, indent=1))
            print("BODY:", body[:2000])
            return


main()

